"""Trailer washout reimbursement for contaminated equipment after delivery.

A washout is reimbursable only when the delivered commodity leaves the trailer needing
cleaning for the next load. The settlement service uses the rules below to decide how
much of a carrier-submitted wash receipt may be passed through to the customer.

Business rules:
- The required wash level is driven by the stronger of the commodity contamination
  class and the next-load requirement supplied by operations.
- Wash levels bill at contract maximums: rinse, standard, sanitize, and hazmat.
- Contracts may disallow pass-through entirely, or may disallow premium hazmat
  reimbursement even when a hazmat wash was operationally required.
- The reimbursable amount is the lesser of the actual receipt and the allowed maximum,
  reduced by any carrier deductible, then rounded to cents.
- Receipts at or below the deductible reimburse zero. Negative receipts and invalid
  combinations are rejected.
- Food-grade commodities require at least a sanitize wash.
- Non-contaminating dry freight does not reimburse unless operations explicitly require
  a wash for the next load.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")

_LEVEL_ORDER = {"none": 0, "rinse": 1, "standard": 2, "sanitize": 3, "hazmat": 4}
_CLASS_MINIMUM = {
    "dry": "none",
    "produce": "rinse",
    "food": "sanitize",
    "chemical": "standard",
    "hazmat": "hazmat",
}
_MAX_BY_LEVEL = {
    "none": Decimal("0.00"),
    "rinse": Decimal("35.00"),
    "standard": Decimal("85.00"),
    "sanitize": Decimal("140.00"),
    "hazmat": Decimal("225.00"),
}


@dataclass(frozen=True)
class WashoutRequest:
    commodity_class: str
    required_wash_level: str
    receipt_amount: Decimal
    food_grade_trailer: bool = False


@dataclass(frozen=True)
class PassThroughTerms:
    allow_pass_through: bool = True
    allow_hazmat_premium: bool = True
    carrier_deductible: Decimal = Decimal("15.00")
    customer_cap: Decimal | None = None


def _validate(request: WashoutRequest, terms: PassThroughTerms) -> None:
    if request.commodity_class not in _CLASS_MINIMUM:
        raise ValueError(f"unknown commodity_class: {request.commodity_class}")
    if request.required_wash_level not in _LEVEL_ORDER:
        raise ValueError(f"unknown required_wash_level: {request.required_wash_level}")
    if request.receipt_amount < 0:
        raise ValueError("receipt_amount cannot be negative")
    if terms.carrier_deductible < 0:
        raise ValueError("carrier_deductible cannot be negative")
    if terms.customer_cap is not None and terms.customer_cap < 0:
        raise ValueError("customer_cap cannot be negative")


def _stronger_level(left: str, right: str) -> str:
    return left if _LEVEL_ORDER[left] >= _LEVEL_ORDER[right] else right


def _required_level(request: WashoutRequest) -> str:
    level = _stronger_level(_CLASS_MINIMUM[request.commodity_class], request.required_wash_level)
    if request.food_grade_trailer and _LEVEL_ORDER[level] < _LEVEL_ORDER["sanitize"]:
        return "sanitize"
    return level


def _allowed_maximum(level: str, terms: PassThroughTerms) -> Decimal:
    if not terms.allow_pass_through:
        return Decimal("0.00")
    if level == "hazmat" and terms.allow_hazmat_premium:
        return _MAX_BY_LEVEL["standard"]
    return _MAX_BY_LEVEL[level]


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_washout_fee(
    request: WashoutRequest, terms: PassThroughTerms = PassThroughTerms()
) -> Decimal:
    """Reimbursable washout amount in dollars, rounded to the cent.

    The payable amount is limited by the required wash level, contract settings,
    optional customer cap, and the carrier deductible.
    """
    _validate(request, terms)
    level = _required_level(request)
    if level == "none":
        return Decimal("0.00")

    allowed = _allowed_maximum(level, terms)
    allowed = _apply_cap(allowed, terms.customer_cap)
    eligible = min(request.receipt_amount, allowed)
    if eligible <= terms.carrier_deductible:
        return Decimal("0.00")

    reimbursable = eligible - terms.carrier_deductible
    return reimbursable.quantize(CENT, rounding=ROUND_HALF_UP)

mode_conversion_factor.py:
"""Equivalent rating factors for converting between freight pricing modes.

Operations normalizes customer rates across truckload, LTL, drayage, and flatbed so
analytics can compare bids on a common basis. The conversion here returns a factor
that multiplies the source mode's amount into an equivalent target-mode amount.

Business rules:
- Base factors are configured per source/target mode pair.
- Weight, distance, and stop count slightly adjust the factor within narrow bands.
- Residential delivery only affects LTL destinations.
- Hazmat applies a small uplift except on drayage, where local port tariffs already
  include most handling.
- Cross-border moves add friction on truckload and flatbed conversions.
- Very short drayage moves under 25 miles use a local minimum factor.
- Flatbed with over-dimensional freight adds an extra uplift.
- Final factors are rounded half up to four decimals and never below 0.2500.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

FOUR_PLACES = Decimal("0.0001")
MIN_FACTOR = Decimal("0.2500")

_BASE_FACTORS = {
    ("truckload", "ltl"): Decimal("1.1800"),
    ("truckload", "drayage"): Decimal("0.7600"),
    ("truckload", "flatbed"): Decimal("1.1200"),
    ("ltl", "truckload"): Decimal("0.8500"),
    ("ltl", "drayage"): Decimal("0.6400"),
    ("ltl", "flatbed"): Decimal("1.0500"),
    ("drayage", "truckload"): Decimal("1.3100"),
    ("drayage", "ltl"): Decimal("1.4200"),
    ("drayage", "flatbed"): Decimal("1.2700"),
    ("flatbed", "truckload"): Decimal("0.9100"),
    ("flatbed", "ltl"): Decimal("1.0900"),
    ("flatbed", "drayage"): Decimal("0.7000"),
}


@dataclass(frozen=True)
class ConversionRequest:
    source_mode: str
    target_mode: str
    weight_lb: int
    distance_miles: int
    stops: int = 2
    residential: bool = False
    hazmat: bool = False
    cross_border: bool = False
    overdimensional: bool = False


@dataclass(frozen=True)
class ConversionTerms:
    heavy_weight_threshold_lb: int = 30000
    long_haul_threshold_miles: int = 1000
    stop_surcharge_per_extra_stop: Decimal = Decimal("0.0150")
    max_stop_surcharge: Decimal = Decimal("0.0600")
    short_drayage_max_miles: int = 25
    short_drayage_factor: Decimal = Decimal("0.5800")


def _validate(req: ConversionRequest) -> None:
    modes = {"truckload", "ltl", "drayage", "flatbed"}
    if req.source_mode not in modes or req.target_mode not in modes:
        raise ValueError("unsupported mode")
    if req.source_mode == req.target_mode:
        raise ValueError("source and target modes must differ")
    if req.weight_lb <= 0 or req.distance_miles <= 0:
        raise ValueError("weight and distance must be positive")
    if req.stops < 1:
        raise ValueError("stops must be at least 1")


def _base_factor(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.source_mode == "drayage" and req.distance_miles <= terms.short_drayage_max_miles:
        if req.target_mode == "truckload":
            return terms.short_drayage_factor
    return _BASE_FACTORS[(req.source_mode, req.target_mode)]


def _weight_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.target_mode == "ltl":
        if req.weight_lb < 5000:
            return Decimal("0.0800")
        if req.weight_lb > 20000:
            return Decimal("-0.0500")
    if req.weight_lb >= terms.heavy_weight_threshold_lb and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("0.0400")
    return Decimal("0.0000")


def _distance_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.distance_miles < 50 and req.target_mode == "ltl":
        return Decimal("0.0600")
    if req.distance_miles >= terms.long_haul_threshold_miles and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("-0.0300")
    return Decimal("0.0000")


def _accessorial_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    adj = Decimal("0.0000")
    extra_stops = max(req.stops - 2, 0)
    stop_adj = terms.stop_surcharge_per_extra_stop * extra_stops
    if stop_adj > terms.max_stop_surcharge:
        stop_adj = terms.max_stop_surcharge
    adj += stop_adj
    if req.residential and req.target_mode == "ltl":
        adj += Decimal("0.0450")
    if req.hazmat:
        adj -= Decimal("0.0100") if req.target_mode == "drayage" else Decimal("0.0250")
    if req.cross_border and req.target_mode in {"truckload", "flatbed"}:
        adj += Decimal("0.0350")
    if req.overdimensional and req.target_mode == "flatbed":
        adj += Decimal("0.0700")
    return adj


def calculate_mode_conversion_factor(
    req: ConversionRequest, terms: ConversionTerms = ConversionTerms()
) -> Decimal:
    """Return the equivalent factor from source mode pricing to target mode pricing."""
    _validate(req)
    factor = _base_factor(req, terms)
    factor += _weight_adjustment(req, terms)
    factor += _distance_adjustment(req, terms)
    factor += _accessorial_adjustment(req, terms)
    if factor < MIN_FACTOR:
        factor = MIN_FACTOR
    return factor.quantize(FOUR_PLACES, rounding=ROUND_HALF_UP)

